func (fence *epochFence) Current() authority.Snapshot {
	return authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Ready: true, Leader: true, Epoch: fence.epoch.Load(), Revision: 1, ExpiresAt: time.Now().Add(time.Hour)}
}

func (fence *epochFence) Guard(_ context.Context, epoch uint64) error {
	if epoch == 0 || epoch != fence.epoch.Load() {
		return authority.ErrFenced
	}
	return nil
}

func testStore(t *testing.T) (*Store, jetstream.KeyValue, *epochFence) {
	t.Helper()
	srv, err := server.NewServer(&server.Options{Host: "127.0.0.1", Port: -1, JetStream: true, StoreDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	fence := &epochFence{}
	fence.epoch.Store(3)
	store, err := Open(t.Context(), js, 1, fence)
	if err != nil {
		t.Fatal(err)
	}
	kv, err := js.KeyValue(t.Context(), Bucket)
	if err != nil {
		t.Fatal(err)
	}
	return store, kv, fence
}

func (seat Seat) validate() error {
	// A drained seat carries its drain time and an undrained one none.
	if !nodeRE.MatchString(seat.Node) || seat.Epoch == 0 || seat.Drain != !seat.DrainedAt.IsZero() {
		return fmt.Errorf("%w: seat %q", ErrInvalid, seat.Node)
	}
	return nil
}

func openReader(ctx context.Context, js jetstream.JetStream, kv jetstream.KeyValue) (*Reader, error) {
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("inspect seat store: %w", err)
	}
	config := status.Config()
	if kv.Bucket() != Bucket || status.Bucket() != Bucket || config.Bucket != Bucket || config.Storage != jetstream.FileStorage || config.TTL != 0 || config.History != 4 || config.MaxValueSize != 4<<10 || config.Replicas != 1 && config.Replicas != 3 && config.Replicas != 5 {
		return nil, fmt.Errorf("%w: existing seat store durability or identity", ErrInvalid)
	}
	options := js.Options()
	legacyOptions := []nats.JSOpt{nats.APIPrefix(options.APIPrefix), nats.MaxWait(options.DefaultTimeout)}
	if options.Domain != "" {
		legacyOptions = append(legacyOptions, nats.Domain(options.Domain))
	}
	leader, err := js.Conn().JetStream(legacyOptions...)
	if err != nil {
		return nil, fmt.Errorf("open ordered seat reader: %w", err)
	}
	return &Reader{kv: kv, leader: leader}, nil
}

func Open(ctx context.Context, js jetstream.JetStream, replicas int, fencer authority.Fencer) (*Store, error) {
	if js == nil || js.Conn() == nil || fencer == nil || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: seat store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Storage: jetstream.FileStorage, Replicas: replicas, History: 4, MaxValueSize: 4 << 10,
	})
	if err != nil {
		return nil, fmt.Errorf("seat store: %w", err)
	}
	reader, err := openReader(ctx, js, kv)
	if err != nil {
		return nil, err
	}
	return &Store{Reader: reader, fencer: fencer}, nil
}

func (s *Reader) Get(ctx context.Context, node string) (Seat, uint64, error) {
	if !nodeRE.MatchString(node) {
		return Seat{}, 0, fmt.Errorf("%w: seat %q", ErrInvalid, node)
	}
	subject := "$KV." + Bucket + "." + node
	// Drain decisions must observe the leader, never a potentially stale replica.
	entry, err := s.leader.GetLastMsg("KV_"+Bucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return Seat{Node: node}, 0, nil
	}
	if err != nil {
		return Seat{}, 0, fmt.Errorf("read seat %s: %w", node, err)
	}
	if entry == nil || entry.Subject != subject || entry.Sequence == 0 || entry.Header.Get("KV-Operation") != "" || entry.Header.Get(jetstream.MarkerReasonHeader) != "" {
		return Seat{}, 0, fmt.Errorf("%w: malformed or deleted seat %s", ErrInvalid, node)
	}
	var seat Seat
	if err := json.Unmarshal(entry.Data, &seat, json.RejectUnknownMembers(true)); err != nil {
		return Seat{}, 0, fmt.Errorf("%w: seat %s: %v", ErrInvalid, node, err)
	}
	if err := seat.validate(); err != nil || seat.Node != node {
		return Seat{}, 0, fmt.Errorf("%w: seat %s holds %q", ErrInvalid, node, seat.Node)
	}
	return seat, entry.Sequence, nil
}

func (s *Store) Put(ctx context.Context, seat Seat, revision uint64) (uint64, error) {
	if err := seat.validate(); err != nil {
		return 0, err
	}
	wire, err := json.Marshal(seat)
	if err != nil {
		return 0, err
	}
	if err := s.fencer.Guard(ctx, seat.Epoch); err != nil {
		return 0, err
	}
	if revision == 0 {
		return s.kv.Create(ctx, seat.Node, wire)
	}
	return s.kv.Update(ctx, seat.Node, wire, revision)
}

func (s *Reader) Drained(ctx context.Context) (map[string]bool, error) {
	keys, err := s.kv.ListKeys(ctx)
	if err != nil {
		return nil, fmt.Errorf("list seats: %w", err)
	}
	defer keys.Stop()
	drained := map[string]bool{}
	for node := range keys.Keys() {
		seat, _, err := s.Get(ctx, node)
		if err != nil {
			return nil, err
		}
		if seat.Drain {
			drained[node] = true
		}
	}
	return drained, nil
}

func (s *Store) Granted(ctx context.Context, node string, desired host.Desired) (bool, error) {
	if desired.Role != terrabase.Role {
		return true, nil
	}
	seat, _, err := s.Get(ctx, node)
	if err != nil {
		return false, err
	}
	return desired.Generation <= seat.Permit, nil
}

func newCell(t *testing.T) *cell {
	return &cell{t: t, now: time.Date(2026, 10, 6, 12, 0, 0, 0, time.UTC),
		desired:  map[string]uint64{"gru-1-db-1": 1, "gru-1-db-2": 1},
		state:    map[string]string{"gru-1-db-1": "running", "gru-1-db-2": "running"},
		backends: map[string]Backend{"10.251.0.21:9465": {Healthy: true}, "10.251.0.22:9465": {Healthy: true}},
		members: []Member{{Node: "gru-1-db-1", Backend: "10.251.0.21:9465", Group: "terrabase"},
			{Node: "gru-1-db-2", Backend: "10.251.0.22:9465", Group: "terrabase"}}}
}

func (c *cell) ListDesired(_ context.Context, role string) ([]host.Desired, error) {
	var out []host.Desired
	for node, generation := range c.desired {
		out = append(out, host.Desired{Node: node, Role: role, Digest: "d", Generation: generation, Withdrawn: c.withdrawn[node]})
	}
	return out, nil
}

func (c *cell) ListHosts(context.Context) ([]host.HostStatus, error) {
	var out []host.HostStatus
	for node, state := range c.state {
		out = append(out, host.HostStatus{Reports: []host.Report{{Node: node, Role: terrabase.Role, Digest: "d",
			Generation: c.desired[node], State: state, ObservedAt: c.now}}})
	}
	return out, nil
}

func (c *cell) controller(store *Store, fence authority.Fencer) *Controller {
	return &Controller{Store: store, Fencer: fence, Hosts: c,
		Seats:    func() ([]Member, error) { return c.members, nil },
		Backends: func(context.Context) (map[string]Backend, error) { return c.backends, nil },
		Now:      func() time.Time { return c.now }, Wake: func() { c.wakes++ }}
}

func (c *cell) release(generation uint64) {
	for node := range c.desired {
		c.desired[node], c.state[node] = generation, "waiting"
	}
}

func (c *cell) tick(controller *Controller) {
	c.t.Helper()
	if err := controller.Tick(c.t.Context()); err != nil {
		c.t.Fatal(err)
	}
}

func (c *cell) expect(store *Store, drained []string, permitted []string) {
	c.t.Helper()
	got, err := store.Drained(c.t.Context())
	if err != nil {
		c.t.Fatal(err)
	}
	if len(got) != len(drained) {
		c.t.Fatalf("drained %v, want %v", got, drained)
	}
	for _, node := range drained {
		if !got[node] {
			c.t.Fatalf("drained %v, want %v", got, drained)
		}
	}
	for _, member := range c.members {
		want := false
		for _, node := range permitted {
			want = want || node == member.Node
		}
		granted, err := store.Granted(c.t.Context(), member.Node, host.Desired{Role: terrabase.Role, Generation: c.desired[member.Node]})
		if err != nil || granted != want {
			c.t.Fatalf("%s permitted=%v err=%v, want %v", member.Node, granted, err, want)
		}
	}
}

func (f staleFence) Current() authority.Snapshot {
	snapshot := f.epochFence.Current()
	snapshot.Epoch--
	return snapshot
}

func (c *Controller) now() time.Time {
	if c.Now != nil {
		return c.Now().UTC()
	}
	return time.Now().UTC()
}

func (c *Controller) Tick(ctx context.Context) error {
	snapshot := c.Fencer.Current()
	if !snapshot.CanMutate() {
		c.ready, c.drained = nil, nil
		return nil
	}
	views, err := c.observe(ctx)
	if err != nil {
		return err
	}
	// Keep only the waits of seats that are drained now, so a seat that
	// left and came back, or was returned, starts them afresh.
	ready, drained := map[string]time.Time{}, map[string]time.Time{}
	for _, v := range views {
		if v.record.Drain {
			if at, ok := c.ready[v.seat.Node]; ok {
				ready[v.seat.Node] = at
			}
			if at, ok := c.drained[v.seat.Node]; ok {
				drained[v.seat.Node] = at
			}
		}
	}
	c.ready, c.drained = ready, drained
	now := c.now()
	busy := map[string]bool{}
	for _, v := range views {
		record, target := v.record, v.desired.Generation
		switch {
		case record.Drain && v.wanted && v.done && record.Permit >= target && (!v.inLB || v.backend.Healthy):
			// Restarted and serving: back to rotation once the seat has kept
			// serving for the settle time, its /readyz included, and the load
			// balancer also finds it healthy. If OCI stopped checking a
			// drained backend the seat stays drained and its group waits,
			// which costs time, never requests. A seat whose desired was
			// withdrawn stays drained, holding its group, while its host stops
			// it: it serves nothing and its group is a member short.
			first, seen := c.ready[v.seat.Node]
			if !seen {
				c.ready[v.seat.Node] = now
				first = now
			}
			if now.Sub(first) < DefaultSettle {
				busy[v.seat.Group] = true
				continue
			}
			delete(c.ready, v.seat.Node)
			record.Drain, record.DrainedAt = false, time.Time{}
			if err := c.put(ctx, snapshot.Epoch, v, record, "returned to rotation"); err != nil {
				return err
			}
		case record.Drain && record.Permit < target:
			// Drained: permit the restart once the load balancer stopped
			// sending it requests and the in-flight grace passed since it
			// was first seen to, not since the drain was asked for: the
			// load balancer may apply it late.
			busy[v.seat.Group] = true
			since := record.DrainedAt
			if v.inLB {
				if !v.backend.Drained {
					delete(c.drained, v.seat.Node)
					continue
				}
				first, seen := c.drained[v.seat.Node]
				if !seen {
					c.drained[v.seat.Node] = now
					first = now
				}
				since = first
			}
			if now.Sub(since) < DefaultDrainGrace {
				continue
			}
			record.Permit = target
			if err := c.put(ctx, snapshot.Epoch, v, record, "restart permitted"); err != nil {
				return err
			}
		case record.Drain, v.wanted && !v.done && record.Permit >= target:
			// Restarting under a permit. A seat that never serves holds
			// its group until a newer desired generation (a rollback)
			// supersedes the permit.
			busy[v.seat.Group] = true
		}
	}
	if c.Hold != nil {
		reason, err := c.Hold(ctx)
		if err != nil {
			return err
		}
		if reason != "" {
			slog.DebugContext(ctx, "terrabase seats wait: "+reason, "component", "seatrollout")
			return nil
		}
	}
	var pending []view
	for _, v := range views {
		if v.wanted && !v.done && v.record.Permit < v.desired.Generation && !v.record.Drain && !busy[v.seat.Group] {
			pending = append(pending, v)
		}
	}
	// Seats the load balancer does not serve go first: restarting them
	// costs no capacity.
	slices.SortFunc(pending, func(a, b view) int {
		if a.serving() != b.serving() {
			if a.serving() {
				return 1
			}
			return -1
		}
		return cmp.Compare(a.seat.Node, b.seat.Node)
	})
	for _, v := range pending {
		if busy[v.seat.Group] {
			continue
		}
		busy[v.seat.Group] = true
		record := v.record
		if !v.serving() {
			record.Permit = v.desired.Generation
			if err := c.put(ctx, snapshot.Epoch, v, record, "restart permitted; the seat serves no requests"); err != nil {
				return err
			}
			continue
		}
		if !slices.ContainsFunc(views, func(other view) bool { return other.seat.Node != v.seat.Node && other.serving() }) {
			slog.DebugContext(ctx, "terrabase seat waits: draining it would leave no healthy seat", "component", "seatrollout", "seat", v.seat.Node)
			continue
		}
		record.Drain, record.DrainedAt = true, now
		if err := c.put(ctx, snapshot.Epoch, v, record, "drained for its restart"); err != nil {
			return err
		}
	}
	return nil
}

func (c *Controller) put(ctx context.Context, epoch uint64, v view, record Seat, what string) error {
	record.Node, record.Epoch = v.seat.Node, epoch
	if _, err := c.Store.Put(ctx, record, v.rev); err != nil {
		return fmt.Errorf("seat %s: %w", v.seat.Node, err)
	}
	if c.Wake != nil {
		c.Wake()
	}
	slog.InfoContext(ctx, "terrabase seat "+what, "component", "seatrollout", "seat", v.seat.Node, "generation", v.desired.Generation, "epoch", epoch)
	return nil
}

func (c *Controller) observe(ctx context.Context) ([]view, error) {
	seats, err := c.Seats()
	if err != nil {
		return nil, err
	}
	desired, err := c.Hosts.ListDesired(ctx, terrabase.Role)
	if err != nil {
		return nil, err
	}
	statuses, err := c.Hosts.ListHosts(ctx)
	if err != nil {
		return nil, err
	}
	backends := map[string]Backend{}
	if c.Backends != nil {
		if backends, err = c.Backends(ctx); err != nil {
			return nil, err
		}
	}
	now := c.now()
	views := make([]view, 0, len(seats))
	for _, seat := range seats {
		record, rev, err := c.Store.Get(ctx, seat.Node)
		if err != nil {
			return nil, err
		}
		v := view{seat: seat, record: record, rev: rev}
		if index := slices.IndexFunc(desired, func(d host.Desired) bool { return d.Node == seat.Node }); index >= 0 {
			v.desired = desired[index]
			v.wanted = !v.desired.Withdrawn && v.desired.ManagedMember == nil
		}
		for _, status := range statuses {
			for _, report := range status.Reports {
				if report.Node == seat.Node && report.Role == terrabase.Role && report.Generation == v.desired.Generation &&
					report.Digest == v.desired.Digest && report.State == "running" && now.Sub(report.ObservedAt) < host.ReportMaxAge {
					v.done = true
				}
			}
		}
		v.backend, v.inLB = backends[seat.Backend]
		if seat.Backend != "" && !v.inLB {
			return nil, fmt.Errorf("seat %s: expected load balancer backend %s is unobserved", seat.Node, seat.Backend)
		}
		v.inLB = v.inLB && seat.Backend != ""
		views = append(views, v)
	}
	return views, nil
}

func (s Snapshot) CanMutate() bool {
	return entityid.Valid(s.DeploymentID) && s.Ready && s.Leader && s.Epoch > 0 && s.Revision > 0 &&
		!s.ExpiresAt.IsZero() && time.Now().Before(s.ExpiresAt)
}

