func useAcceptedController(t *testing.T, accepted bootstrapstart.AcceptedIdentity, roots trust.Keyring) {
	t.Helper()
	oldIdentity, oldTrust, oldGate, oldProbe := acceptedIdentity, acceptedTrustInputs, acceptedPrestart, checkAcceptedBinary
	oldPresent, oldCompletion := acceptedJournalPresent, completionProbe
	acceptedIdentity = func() (bootstrapstart.AcceptedIdentity, error) { return accepted.Clone(), nil }
	acceptedTrustInputs = func(record bootstrapstart.AcceptedIdentity) (bootstrapstart.TrustInputs, error) {
		if err := record.Validate(); err != nil {
			return bootstrapstart.TrustInputs{}, err
		}
		verified, err := trust.VerifyRootChain(roots, trust.ChainIdentity{DeploymentID: record.DeploymentID, Environment: record.Environment, Cell: strings.ToLower(record.Cell)}, trust.RootChain{Version: 1})
		return bootstrapstart.TrustInputs{ChainIdentity: trust.ChainIdentity{DeploymentID: record.DeploymentID, Environment: record.Environment, Cell: strings.ToLower(record.Cell)}, Genesis: roots, Chain: trust.RootChain{Version: 1}, Roots: verified}, err
	}
	acceptedPrestart = func(bootstrapstart.AcceptedIdentity) error { return nil }
	acceptedJournalPresent = func() (bool, error) { return false, nil }
	checkAcceptedBinary = func(context.Context, string, bootstrapstart.AcceptedIdentity) error { return nil }
	t.Cleanup(func() {
		acceptedIdentity, acceptedTrustInputs, acceptedPrestart, checkAcceptedBinary = oldIdentity, oldTrust, oldGate, oldProbe
		acceptedJournalPresent, completionProbe = oldPresent, oldCompletion
	})
}

func signAcceptedSuccessor(t *testing.T, data []byte, now time.Time, root ed25519.PrivateKey, roots trust.Keyring) ([]byte, []byte) {
	t.Helper()
	public, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(public)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	source := strings.Repeat("e", 40)
	delegation, err := release.SignUpdateDelegation(release.BinaryUpdateDelegation{
		Schema: release.UpdateDelegationSchema, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Environment: "canary", Architectures: []string{runtime.GOARCH}, Repository: release.QualificationRepository,
		Workflow: release.QualificationWorkflow, Ref: release.LineageRef, LineageBase: source,
	}, now.Add(-time.Minute), now.Add(time.Hour), root)
	if err != nil {
		t.Fatal(err)
	}
	delegationWire, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	binary := release.BinaryReceipt{Schema: release.BinarySchema, SourceRevision: source, GoVersion: release.DefaultGoVersion, GOOS: "linux", GOARCH: runtime.GOARCH,
		ELFMachine: map[string]string{"amd64": "Advanced Micro Devices X86-64", "arm64": "AArch64"}[runtime.GOARCH], Static: true,
		Bytes: int64(len(data)), SHA256: acceptedDigest(data), QualificationSHA256: acceptedDigest([]byte("qualification"))}
	qualified := release.ProductionQualification{Schema: release.ProductionQualificationSchema,
		Candidate: release.ProductionExpectation{SourceRevision: source, ArtifactSHA256: binary.SHA256,
			QualificationSHA256: binary.QualificationSHA256, Cell: "GRU", Environment: "canary",
			Runtime: release.ProductionRuntime, Architecture: runtime.GOARCH, Role: "orchestrator"}}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		evidence := []byte("test-only " + gate + " evidence")
		qualified.Evidence = append(qualified.Evidence, release.ProductionGateEvidence{Gate: gate,
			SHA256: acceptedDigest(evidence), Bytes: int64(len(evidence)), CompletedAt: now.Add(-time.Second)})
	}
	payload, err := trust.EncodePayload(qualified)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := trust.Sign(payload, release.ProductionQualificationScope(qualified.Candidate), now, now.Add(30*time.Minute), root)
	if err != nil {
		t.Fatal(err)
	}
	proofWire, err := trust.EncodeEnvelope(proof)
	if err != nil {
		t.Fatal(err)
	}
	update := release.BinaryUpdateReceipt{Schema: release.UpdateReceiptSchema, Binary: binary, Cell: "GRU",
		DelegationSHA256: acceptedDigest(delegationWire), Production: &release.ProductionProof{Qualification: proofWire},
		Lineage: release.SourceLineage{Repository: release.QualificationRepository, Workflow: release.QualificationWorkflow,
			Ref: release.LineageRef, LineageBase: source, QualificationRunID: 10, QualificationRunNum: 5}}
	payload, err = trust.EncodePayload(update)
	if err != nil {
		t.Fatal(err)
	}
	receipt, err := trust.Sign(payload, release.UpdateReceiptScope(update, "canary"), now, now.Add(30*time.Minute), leaf)
	if err != nil {
		t.Fatal(err)
	}
	receiptWire, err := trust.EncodeEnvelope(receipt)
	if err != nil {
		t.Fatal(err)
	}
	return receiptWire, delegationWire
}

func (identity AcceptedIdentity) Clone() AcceptedIdentity {
	identity.ControllerSlots = slices.Clone(identity.ControllerSlots)
	identity.ControllerBindings = slices.Clone(identity.ControllerBindings)
	identity.ConfigSHA256 = maps.Clone(identity.ConfigSHA256)
	identity.LaunchMaterialSHA256 = maps.Clone(identity.LaunchMaterialSHA256)
	identity.MaterialReferences = slices.Clone(identity.MaterialReferences)
	if identity.ManagedMaterial != nil {
		identity.ManagedMaterial = new(*identity.ManagedMaterial)
	}
	return identity
}

func (identity AcceptedIdentity) Validate() error {
	if identity.SchemaVersion != 1 || !entityid.Valid(identity.OperationID) || !entityid.Valid(identity.DeploymentID) ||
		identity.Origin != identityrekey.AcceptanceOriginInitial && identity.Origin != identityrekey.AcceptanceOriginRekey ||
		!entityid.Valid(identity.ClusterID) || !release.ValidEnvironment(identity.Environment) || !catalog.IsCell(identity.Cell) ||
		!slices.Equal(identity.ControllerSlots, []string{"controller-a", "controller-b", "controller-c"}) ||
		!slices.Contains(identity.ControllerSlots, identity.Slot) || !slices.Contains(identity.ControllerSlots, identity.SeedSlot) ||
		len(identity.ControllerBindings) == 0 || len(identity.ControllerBindings) > 3 ||
		identity.AcceptedAt.IsZero() || identity.AcceptedAt.Location() != time.UTC ||
		identity.MaterialGenerationSHA256 != "" && !markerDigestRE.MatchString(identity.MaterialGenerationSHA256) ||
		identity.ManagedMaterial != nil && identity.ManagedMaterial.Validate() != nil {
		return ErrAcceptedIdentity
	}
	if err := validateAcceptedBroker(identity.Broker); err != nil {
		return err
	}
	localFound := false
	for i, binding := range identity.ControllerBindings {
		if !slices.Contains(identity.ControllerSlots, binding.Slot) || binding.validate(identity.Cell) != nil ||
			i > 0 && identity.ControllerBindings[i-1].Slot >= binding.Slot {
			return ErrAcceptedIdentity
		}
		if binding.Slot == identity.Slot {
			if binding != identity.localBinding() {
				return ErrAcceptedIdentity
			}
			localFound = true
		}
		for _, prior := range identity.ControllerBindings[:i] {
			if prior.InstanceOCID == binding.InstanceOCID || prior.PrimaryVNICOCID == binding.PrimaryVNICOCID ||
				prior.PrimaryPrivateIP == binding.PrimaryPrivateIP || prior.Store.ServerName == binding.Store.ServerName ||
				prior.Store.RaftNodeID == binding.Store.RaftNodeID {
				return ErrAcceptedIdentity
			}
		}
	}
	if !localFound || len(identity.ConfigSHA256) != 4 || !markerDigestRE.MatchString(identity.ConfigSHA256["controller.json"]) {
		return ErrAcceptedIdentity
	}
	for _, name := range bootstrap.ControllerConfigFileNames {
		if !markerDigestRE.MatchString(identity.ConfigSHA256[name]) {
			return ErrAcceptedIdentity
		}
	}
	if identityrekey.ValidateLaunchMaterialPins(identity.LaunchMaterialSHA256) != nil {
		return ErrAcceptedIdentity
	}
	return validateAcceptedReferences(identity)
}

func EncodeAcceptedIdentity(identity AcceptedIdentity) ([]byte, error) {
	if err := identity.Validate(); err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(identity)
	if err != nil || len(wire) > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	return wire, nil
}

func DecodeAcceptedIdentity(wire []byte) (AcceptedIdentity, error) {
	var identity AcceptedIdentity
	if err := protocol.DecodeStrict(wire, &identity, MaxAcceptedIdentityBytes); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("%w: %v", ErrAcceptedIdentity, err)
	}
	canonical, err := EncodeAcceptedIdentity(identity)
	if err != nil || !bytes.Equal(wire, canonical) {
		return AcceptedIdentity{}, ErrAcceptedIdentity
	}
	return identity, nil
}

func VerifyRootChain(genesis Keyring, id ChainIdentity, chain RootChain) (VerifiedRoots, error) {
	if chain.Version != 1 || len(genesis) == 0 || len(genesis) > MaxRootSet || len(chain.Rotations) > MaxRotations {
		return VerifiedRoots{}, fmt.Errorf("%w: root chain genesis or length", ErrInvalid)
	}
	if err := RotationScope(id, 1).validate(); err != nil {
		return VerifiedRoots{}, err
	}
	verified := VerifiedRoots{Current: maps.Clone(genesis), Historical: maps.Clone(genesis), Head: RootSetDigest(genesis)}
	for index, signed := range chain.Rotations {
		next, payload, err := verifyRotation(signed, id, verified)
		if err != nil {
			return VerifiedRoots{}, fmt.Errorf("root rotation %d: %w", index+1, err)
		}
		sum := sha256.Sum256(payload)
		verified.Current, verified.Sequence, verified.Head = next, verified.Sequence+1, hex.EncodeToString(sum[:])
		maps.Copy(verified.Historical, next)
	}
	return verified, nil
}

func (layout Layout) validate() error {
	if !filepath.IsAbs(layout.Root) || filepath.Clean(layout.Root) != layout.Root || layout.Owner < 0 {
		return fmt.Errorf("%w: release root must be a clean absolute path", ErrInvalid)
	}
	return nil
}

func (layout Layout) ensureDirs() error {
	if err := layout.validate(); err != nil {
		return err
	}
	for _, path := range []string{layout.Root, layout.releasesPath()} {
		// The units run with UMask=0077; set the mode explicitly so the
		// unprivileged controller can traverse to its binary.
		if err := os.Mkdir(path, 0o755); err == nil {
			if err := os.Chmod(path, 0o755); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return err
		}
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	return nil
}

func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

func (layout Layout) Delegate() (string, error) {
	digest, err := layout.KnownGood()
	if err != nil || digest == "" {
		return "", err
	}
	if _, err := os.Lstat(filepath.Join(layout.ReleaseDir(digest), bakedMarkerFile)); err == nil {
		return "", nil
	}
	knownBad, err := layout.KnownBad()
	if err != nil || knownBad[digest] {
		return "", err
	}
	return digest, layout.VerifyRelease(digest)
}

func (layout Layout) VerifyRelease(digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: release digest", ErrInvalid)
	}
	for _, path := range []string{layout.Root, layout.releasesPath(), layout.ReleaseDir(digest)} {
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	path := layout.BinaryPath(digest)
	if err := layout.checkOwned(path, false); err != nil {
		return err
	}
	observed, _, err := hashFile(path)
	if err != nil {
		return err
	}
	if observed != digest {
		return fmt.Errorf("%w: release %s bytes changed", ErrUnsafe, digest)
	}
	return nil
}

func (layout Layout) flipLink(name, digest string) error {
	temporary := filepath.Join(layout.Root, "."+name+"-"+digest[:16])
	_ = os.Remove(temporary)
	if err := os.Symlink(releasesDir+"/"+digest, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, name)); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return syncDir(layout.Root)
}

func hashFile(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, MaxBinaryBytes+1))
	if err != nil {
		return "", 0, err
	}
	if size > MaxBinaryBytes {
		return "", 0, fmt.Errorf("%w: binary exceeds %d bytes", ErrInvalid, MaxBinaryBytes)
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func syncDir(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, "."+filepath.Base(path)+"-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(mode); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	return syncDir(directory)
}

func readBounded(path string, maximum int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%w: %s is not a regular file", ErrInvalid, path)
	}
	data, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%w: %s is too large", ErrInvalid, path)
	}
	return data, nil
}

func (layout Layout) Lock() (func(), error) {
	if err := layout.ensureDirs(); err != nil {
		return nil, err
	}
	path := filepath.Join(layout.Root, lockFile)
	fd, err := syscall.Open(path, syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	if err := layout.checkOwned(path, false); err != nil {
		file.Close()
		return nil, err
	}
	for {
		err = syscall.Flock(fd, syscall.LOCK_EX)
		if !errors.Is(err, syscall.EINTR) {
			break
		}
	}
	if err != nil {
		file.Close()
		return nil, &os.PathError{Op: "flock", Path: path, Err: err}
	}
	return func() { file.Close() }, nil
}

func (policy ReceiptPolicy) Verify(receiptWire, delegationWire []byte, now time.Time) (release.VerifiedBinary, error) {
	if len(policy.Roots) == 0 {
		return release.VerifiedBinary{}, fmt.Errorf("%w: no release trust roots", ErrInvalid)
	}
	envelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	var verified release.VerifiedBinary
	switch envelope.Scope.Domain {
	case release.BinaryDomain:
		return release.VerifiedBinary{}, fmt.Errorf("%w: self-update requires a region-qualified update receipt", release.ErrProductionQualification)
	case release.UpdateReceiptDomain:
		verified, err = release.VerifyQualifiedBinaryUpdateCurrent(receiptWire, delegationWire, policy.Roots,
			release.UpdateExpectation{Environment: policy.Environment, Cell: policy.Cell, Architecture: policy.Architecture}, now)
	default:
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt domain %q", ErrInvalid, envelope.Scope.Domain)
	}
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	if !verified.IsVerified() || verified.Receipt().GOARCH != policy.Architecture {
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt architecture differs from this node", release.ErrExpectationMismatch)
	}
	return verified, nil
}

func Stage(layout Layout, source io.Reader, receiptWire, delegationWire []byte, verifier Verifier, now time.Time) (string, error) {
	if source == nil || verifier == nil {
		return "", fmt.Errorf("%w: stage source and verifier are required", ErrInvalid)
	}
	verified, err := verifier.Verify(receiptWire, delegationWire, now)
	if err != nil {
		return "", fmt.Errorf("verify release receipt: %w", err)
	}
	receipt := verified.Receipt()
	if knownBad, err := layout.KnownBad(); err != nil {
		return "", err
	} else if knownBad[receipt.SHA256] {
		return "", ErrKnownBad
	}
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(receipt.SHA256)); err == nil {
		if err := layout.VerifyRelease(receipt.SHA256); err != nil {
			return "", err
		}
		return receipt.SHA256, nil
	}
	if err := layout.install(source, receipt.SHA256, receipt.Bytes, map[string][]byte{
		receiptFile: receiptWire, delegationFile: delegationWire,
	}); err != nil {
		return "", err
	}
	return receipt.SHA256, nil
}

func (layout Layout) ReleaseReceipt(digest string) (receiptWire, delegationWire []byte, err error) {
	if err := layout.VerifyRelease(digest); err != nil {
		return nil, nil, err
	}
	wires := make([][]byte, 2)
	for index, name := range []string{receiptFile, delegationFile} {
		path := filepath.Join(layout.ReleaseDir(digest), name)
		if err := layout.checkOwned(path, false); err != nil {
			return nil, nil, err
		}
		if wires[index], err = readBounded(path, trust.MaxEnvelopeBytes); err != nil {
			return nil, nil, err
		}
	}
	return wires[0], wires[1], nil
}

func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

func (layout Layout) install(source io.Reader, digest string, size int64, metadata map[string][]byte) error {
	if !digestRE.MatchString(digest) || size <= 0 || size > MaxBinaryBytes {
		return fmt.Errorf("%w: release identity", ErrInvalid)
	}
	temporary, err := os.MkdirTemp(layout.releasesPath(), ".staging-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(temporary)
	if err := os.Chmod(temporary, 0o755); err != nil {
		return err
	}
	binary, err := os.OpenFile(filepath.Join(temporary, BinaryName), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o500)
	if err != nil {
		return err
	}
	hash := sha256.New()
	written, copyErr := io.Copy(io.MultiWriter(binary, hash), io.LimitReader(source, size+1))
	if copyErr == nil {
		copyErr = binary.Chmod(0o555)
	}
	if copyErr == nil {
		copyErr = binary.Sync()
	}
	if closeErr := binary.Close(); copyErr == nil {
		copyErr = closeErr
	}
	if copyErr != nil {
		return copyErr
	}
	if written != size || hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: staged binary differs from its signed size or digest", ErrInvalid)
	}
	for name, data := range metadata {
		if err := writeSyncedFile(filepath.Join(temporary, name), data, 0o444); err != nil {
			return err
		}
	}
	if err := syncDir(temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, layout.ReleaseDir(digest)); err != nil {
		return err
	}
	if err := syncDir(layout.releasesPath()); err != nil {
		return err
	}
	return layout.VerifyRelease(digest)
}

func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

func (layout Layout) RecoveryActivation() (Activation, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, errors.Join(ErrInvalid, err)
	}
	if _, err := decodeActivation(data); !errors.Is(err, ErrUnreadableActivation) {
		return Activation{}, ErrInvalid
	}
	var pins struct {
		Target   string `json:"target"`
		Previous string `json:"previous"`
		Unit     string `json:"unit"`
	}
	if err := json.Unmarshal(data, &pins); err != nil ||
		!digestRE.MatchString(pins.Target) || !digestRE.MatchString(pins.Previous) ||
		pins.Target == pins.Previous || !unitRE.MatchString(pins.Unit) {
		return Activation{}, errors.Join(ErrUnreadableActivation, err)
	}
	return Activation{Target: pins.Target, Previous: pins.Previous, Unit: pins.Unit}, nil
}

func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

func decodeActivation(data []byte) (Activation, error) {
	var activation Activation
	if err := protocol.DecodeStrict(data, &activation, maxStateBytes); err != nil {
		return Activation{}, fmt.Errorf("%w: activation record: %w", ErrUnreadableActivation, err)
	}
	if err := activation.validate(); err != nil {
		return Activation{}, fmt.Errorf("%w: %w", ErrUnreadableActivation, err)
	}
	return activation, nil
}

func Activate(layout Layout, digest, unit string, now time.Time, window time.Duration) (Activation, error) {
	if window < MinProofWindow || window > MaxProofWindow || !unitRE.MatchString(unit) || now.IsZero() {
		return Activation{}, fmt.Errorf("%w: activation unit or proof window", ErrInvalid)
	}
	// An interrupted rollout restore is finished before the selection
	// changes again, so its recovery can never overwrite this activation.
	if err := layout.finishRestores(); err != nil {
		return Activation{}, err
	}
	if pending, exists, err := layout.Pending(); err != nil {
		return Activation{}, err
	} else if exists {
		if pending.Target == digest && pending.Unit == unit {
			// A retry passes the same gates as a fresh activation: a crash
			// after a rollback marked the target known bad must not
			// re-activate it, and unverified bytes never become current.
			if !now.Before(pending.Deadline) {
				return Activation{}, fmt.Errorf("%w: activation %s passed its deadline; the watchdog resolves it", ErrInvalid, pending.ActivationID)
			}
			if knownBad, err := layout.KnownBad(); err != nil {
				return Activation{}, err
			} else if knownBad[digest] {
				return Activation{}, ErrKnownBad
			}
			if err := layout.VerifyRelease(digest); err != nil {
				return Activation{}, err
			}
			return pending, layout.flipCurrent(digest)
		}
		return Activation{}, fmt.Errorf("%w: activation %s is still pending", ErrInvalid, pending.ActivationID)
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return Activation{}, err
	} else if knownBad[digest] {
		return Activation{}, ErrKnownBad
	}
	previous, err := layout.Current()
	if err != nil {
		return Activation{}, err
	}
	if previous == "" {
		return Activation{}, fmt.Errorf("%w: seed the baked release before activating another", ErrInvalid)
	}
	if previous == digest {
		return Activation{}, fmt.Errorf("%w: release is already current", ErrInvalid)
	}
	for _, release := range []string{previous, digest} {
		if err := layout.VerifyRelease(release); err != nil {
			return Activation{}, err
		}
	}

	activation := Activation{
		Schema: ActivationSchema, ActivationID: entityid.NewAt(now), Unit: unit,
		Target: digest, Previous: previous, ActivatedAt: now.UTC(), Deadline: now.UTC().Add(window),
	}
	encoded, err := protocol.EncodeJSON(activation)
	if err != nil {
		return Activation{}, err
	}
	if err := writeFileAtomic(layout.activationPath(), encoded, 0o644); err != nil {
		return Activation{}, err
	}
	if err := layout.flipCurrent(digest); err != nil {
		return activation, err
	}
	recordActivation(activation)
	return activation, nil
}

func (layout Layout) KnownBad() (map[string]bool, error) {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	var state knownBadState
	if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
		return nil, err
	}
	known := make(map[string]bool, len(state.Digests))
	for _, digest := range state.Digests {
		if !digestRE.MatchString(digest) {
			return nil, fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
		known[digest] = true
	}
	return known, nil
}

func (layout Layout) markKnownBad(digest string) error {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	var state knownBadState
	switch {
	case errors.Is(err, os.ErrNotExist):
	case err != nil:
		return err
	default:
		if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
			return err
		}
	}
	if slices.Contains(state.Digests, digest) {
		return nil
	}
	state.Digests = append(state.Digests, digest)
	if len(state.Digests) > maxKnownBad {
		state.Digests = state.Digests[len(state.Digests)-maxKnownBad:]
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	return writeFileAtomic(layout.knownBadPath(), encoded, 0o644)
}

func VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation, now time.Time) (VerifiedBinary, error) {
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return VerifiedBinary{}, err
	}
	if receipt.Production == nil {
		return VerifiedBinary{}, fmt.Errorf("%w: signed update contains no independent qualification", ErrProductionQualification)
	}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots,
		productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return VerifiedBinary{}, err
	}
	qualification, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if qualification.ExpiresAt.Before(binary.proof.expiresAt) {
		binary.proof.expiresAt = qualification.ExpiresAt
	}
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return VerifiedBinary{}, err
		}
		if delegation.ExpiresAt.Before(binary.proof.expiresAt) {
			binary.proof.expiresAt = delegation.ExpiresAt
		}
	}
	return binary, nil
}

func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

func run(ctx context.Context, args []string, output io.Writer, now func() time.Time, restart Restarter) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	writer := commandio.NewWriter(output)
	if len(args) == 0 || args[0] == "--help" || args[0] == "-h" || args[0] == "help" {
		_, err := io.WriteString(writer, usage)
		return errors.Join(err, writer.Err())
	}
	c := command{ctx: ctx, output: writer, now: now, restart: restart}
	var err error
	switch args[0] {
	case "check-accepted-identity":
		err = checkAcceptedIdentity(os.Stdin, args[1:])
	case "prepare":
		err = c.prepare(args[1:])
	case "watchdog":
		err = c.watchdog(args[1:])
	case "stage":
		err = c.stage(args[1:])
	case "activate":
		err = c.activate(args[1:])
	case "status":
		err = c.status(args[1:])
	default:
		err = fmt.Errorf("unknown selfupdate command %q", args[0])
	}
	return errors.Join(err, writer.Err())
}

func (c command) prepare(args []string) error {
	flags := flag.NewFlagSet("prepare", flag.ContinueOnError)
	layout := addLayout(flags)
	proof := addProof(flags)
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	baked := flags.String("baked-binary", selfupdate.DefaultBakedBinary, "image-installed binary")
	systemd := flags.String("systemd-dir", "/etc/systemd/system", "unit directory that takes the node's self-update drop-ins")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, err := controllerTrust(*unit)
	if err != nil {
		return err
	}
	rollbackOnly := false
	if accepted != nil {
		rollbackOnly, err = c.checkControllerRecovery(layout.layout(), *accepted, inputs, true, *baked)
		if err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			if rollbackOnly {
				return err
			}
			current, currentErr := layout.layout().Current()
			good, goodErr := layout.layout().KnownGood()
			if currentErr != nil || goodErr != nil || current == "" || good == "" {
				return errors.Join(err, currentErr, goodErr)
			}
			if err := c.checkControllerRelease(layout.layout(), current, *accepted, inputs); err != nil {
				return err
			}
			if err := c.checkControllerRelease(layout.layout(), good, *accepted, inputs); err != nil {
				return err
			}
			_, printErr := fmt.Fprintf(c.output, "selfupdate prepare unit=%s held: compatible current and known-good; no effects\n", *unit)
			return printErr
		}
	}
	// The runtime secret mounts below belong to the host (TS-745).
	if layout.layout().Root == selfupdate.DefaultRoot {
		if moved, err := selfupdate.RunInHostMounts(c.ctx, c.output, os.Stderr); moved || err != nil {
			return err
		}
	}
	if !rollbackOnly && c.delegate(layout.layout(), append([]string{"prepare"}, args...)) {
		if err := c.backstopPrepare(layout.layout(), *unit); err != nil {
			return err
		}
		unlock, err := layout.layout().Lock()
		if err != nil {
			return err
		}
		defer unlock()
		if err := c.installCurrentNetBirdAgent(layout.layout(), *systemd, *unit); err != nil {
			slog.Warn("self-update could not prepare the NetBird worker", "error", err)
		}
		return nil
	}
	check, err := proof.check(*layout.root, *unit)
	if err != nil {
		return err
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	defer unlock()
	accepted, inputs, err = controllerTrust(*unit)
	if err != nil {
		return err
	}
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout.layout(), *accepted, inputs, true, *baked); err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
		if _, err := c.recoverControllerActivation(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	outcome, err := selfupdate.Prepare(layout.layout(), *unit, *baked, check, c.now())
	if err != nil {
		return err
	}
	current, err := layout.layout().Current()
	if err != nil {
		return err
	}
	if _, err = fmt.Fprintf(c.output, "selfupdate prepare unit=%s outcome=%s current=%s\n", *unit, outcome, current); err != nil {
		return err
	}
	// The controller process cannot write its credential directory or
	// controller.json; its armed material generation installs here (TS-668).
	if *unit == selfupdate.ControllerUnit {
		material, err := installGeneration(c.now())
		if err != nil {
			return err
		}
		if material != "" {
			if _, err := fmt.Fprintf(c.output, "selfupdate prepare material-generation: %s\n", material); err != nil {
				return err
			}
		}
	}
	// A node whose image predates a drop-in gets it from the release that
	// runs this step; a failure must not stop the unit's start.
	changed := false
	for _, dropin := range []struct {
		name    string
		install func(string) (bool, error)
	}{{"host-setup", selfupdate.InstallHostSetupDropin}, {"bootstrap", selfupdate.InstallBootstrapDropin},
		{"controller-install", selfupdate.InstallControllerInstallDropin}, {"watchdog", selfupdate.InstallWatchdogLoggingDropin}} {
		if installed, err := dropin.install(*systemd); err != nil {
			slog.Warn("self-update could not install the "+dropin.name+" drop-in", "error", err)
		} else if installed {
			changed = true
			if _, err := fmt.Fprintf(c.output, "selfupdate prepare installed the %s drop-in\n", dropin.name); err != nil {
				return err
			}
		}
	}
	if err := c.installCurrentNetBirdAgent(layout.layout(), *systemd, *unit); err != nil {
		slog.Warn("self-update could not prepare the NetBird worker", "error", err)
	}
	// The drop-ins belong to other units, which read them at their next
	// start once systemd reloads.
	if changed {
		if err := daemonReload(c.ctx); err != nil {
			slog.Warn("self-update could not reload systemd; the drop-ins apply from the next boot", "error", err)
		}
	}
	// The unit's runtime secrets live in memory (TS-745); this root step
	// mounts their directories before the unit's process starts. A failure
	// must not fail prepare (the baked fallback would run instead): the host
	// agent refuses to write those secrets to disk.
	if layout.layout().Root == selfupdate.DefaultRoot {
		if err := memoryRuntime(*unit); err != nil {
			slog.Warn("self-update could not mount the runtime secrets in memory", "unit", *unit, "error", err)
		}
	}
	return nil
}

func (c command) watchdog(args []string) error {
	flags := flag.NewFlagSet("watchdog", flag.ContinueOnError)
	layout := addLayout(flags)
	proof := addProof(flags)
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, err := controllerTrust(*unit)
	if err != nil {
		return err
	}
	rollbackOnly := false
	if accepted != nil {
		rollbackOnly, err = c.checkControllerRecovery(layout.layout(), *accepted, inputs, false, "")
		if err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	delegated := !rollbackOnly && c.delegate(layout.layout(), append([]string{"watchdog"}, args...))
	var check selfupdate.ProofCheck
	if !delegated {
		var err error
		if check, err = proof.check(*layout.root, *unit); err != nil {
			return err
		}
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	accepted, inputs, err = controllerTrust(*unit)
	if err != nil {
		unlock()
		return err
	}
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout.layout(), *accepted, inputs, false, ""); err != nil {
			unlock()
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if _, err := c.recoverControllerActivation(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
	}
	var outcome selfupdate.Outcome
	var activation selfupdate.Activation
	if delegated {
		outcome, activation, err = selfupdate.Backstop(layout.layout(), c.now())
	} else {
		outcome, activation, err = selfupdate.Watch(layout.layout(), *unit, check, c.now())
	}
	if err != nil {
		unlock()
		return err
	}
	// The rollout step runs after the check, so a slow or stuck step never
	// delays a rollback, and before the restart below serves what it owes.
	if !delegated && (*unit == selfupdate.ControllerUnit || *unit == selfupdate.HostUnit) && *proof.config != "" {
		unlock()
		c.rolloutStep(layout.layout(), *unit, *proof.config)
		if unlock, err = layout.layout().Lock(); err != nil {
			return err
		}
	}
	// A rollback leaves a restart obligation until the unit restarts, so a
	// failed systemctl call, an output error or a crash after the link moved
	// is retried by the next timer run instead of reading as idle.
	owed, err := layout.layout().RestartPending(*unit)
	unlock()
	if err != nil {
		return err
	}
	// An idle run runs every 15 s and says nothing. A pending run also repeats
	// every 15 s while an activation waits, so it is debug; rollbacks are warnings.
	if outcome != selfupdate.OutcomeIdle {
		level := slog.LevelInfo
		switch outcome {
		case selfupdate.OutcomePending:
			level = slog.LevelDebug
		case selfupdate.OutcomeRolledBack:
			level = slog.LevelWarn
		}
		slog.Log(c.ctx, level, "selfupdate watchdog", observability.ComponentKey, "selfupdate",
			"unit", *unit, "outcome", string(outcome), "activation", activation.ActivationID, "target", activation.Target)
	}
	if owed {
		if err := c.restart(c.ctx, *unit); err != nil {
			return err
		}
		unlock, err := layout.layout().Lock()
		if err != nil {
			return err
		}
		defer unlock()
		return layout.layout().ClearRestartPending(*unit)
	}
	return nil
}

func (c command) activate(args []string) error {
	flags := flag.NewFlagSet("activate", flag.ContinueOnError)
	layout := addLayout(flags)
	digest := flags.String("release", "", "staged release SHA-256")
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	window := flags.Duration("proof-window", 5*time.Minute, "deadline for the new process's signed version proof")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, gateErr := controllerTrust(*unit)
	if gateErr != nil {
		return gateErr
	}
	if accepted != nil {
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	accepted, inputs, gateErr = controllerTrust(*unit)
	if gateErr != nil {
		unlock()
		return gateErr
	}
	if accepted != nil {
		if err := c.checkControllerRelease(layout.layout(), *digest, *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if err := c.checkControllerTransitions(layout.layout(), *accepted, inputs, true, ""); err != nil {
			unlock()
			return err
		}
	}
	activation, err := selfupdate.Activate(layout.layout(), *digest, *unit, c.now(), *window)
	unlock()
	if err != nil {
		return err
	}
	if _, err := fmt.Fprintf(c.output, "selfupdate activated release=%s previous=%s activation=%s deadline=%s\n",
		activation.Target, activation.Previous, activation.ActivationID, activation.Deadline.Format(time.RFC3339)); err != nil {
		return err
	}
	return c.restart(c.ctx, *unit)
}

func (c command) backstopPrepare(layout selfupdate.Layout, unit string) error {
	unlock, err := layout.Lock()
	if err != nil {
		return err
	}
	defer unlock()
	accepted, inputs, err := controllerTrust(unit)
	if err != nil {
		return err
	}
	recovered := false
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout, *accepted, inputs, true, ""); err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout, *accepted, inputs); err != nil {
			return err
		}
		recovered, err = c.recoverControllerActivation(layout, *accepted, inputs)
		if err != nil {
			return err
		}
	}
	outcome, activation, err := selfupdate.Backstop(layout, c.now())
	if err != nil {
		return err
	}
	// This start serves the restart the rollback owes the unit.
	if recovered || outcome == selfupdate.OutcomeRolledBack && activation.Unit == unit {
		if err := layout.ClearRestartPending(unit); err != nil {
			return err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return err
	}
	if err := layout.VerifyRelease(current); err != nil {
		return fmt.Errorf("current release does not verify: %w", err)
	}
	return nil
}

func controllerTrust(unit string) (*bootstrapstart.AcceptedIdentity, bootstrapstart.TrustInputs, error) {
	if unit != selfupdate.ControllerUnit {
		return nil, bootstrapstart.TrustInputs{}, nil
	}
	accepted, err := acceptedIdentity()
	if errors.Is(err, os.ErrNotExist) {
		present, journalErr := acceptedJournalPresent()
		if journalErr != nil {
			return nil, bootstrapstart.TrustInputs{}, journalErr
		}
		if present {
			return nil, bootstrapstart.TrustInputs{}, errors.New("identity rekey journal exists without accepted controller identity")
		}
		return nil, bootstrapstart.TrustInputs{}, nil
	}
	if err != nil {
		return nil, bootstrapstart.TrustInputs{}, err
	}
	if err := accepted.Validate(); err != nil {
		return nil, bootstrapstart.TrustInputs{}, err
	}
	if err := acceptedPrestart(accepted); err != nil {
		return nil, bootstrapstart.TrustInputs{}, err
	}
	inputs, err := acceptedTrustInputs(accepted)
	return new(accepted), inputs, err
}

func (c command) requireControllerCompletion(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) error {
	present, err := acceptedJournalPresent()
	if err != nil || !present {
		return err
	}
	current, err := layout.Current()
	if err != nil || current == "" {
		return errors.New("identity rekey completion requires a trusted current binary")
	}
	rollback, err := c.controllerRollback(layout, accepted, inputs)
	if err != nil {
		return err
	}
	if current == rollback.Target {
		current = rollback.Previous
	}
	if err := c.checkControllerRelease(layout, current, accepted, inputs); err != nil {
		return err
	}
	return completionProbe(c.ctx, layout.BinaryPath(current))
}

func (c command) installCurrentNetBirdAgent(layout selfupdate.Layout, systemd, unit string) error {
	// Packaged worker and enrollment units execute the image's default release tree.
	if layout.Root != selfupdate.DefaultRoot {
		return fmt.Errorf("managed NetBird units require --root %s; configured root is %s", selfupdate.DefaultRoot, layout.Root)
	}
	current, err := layout.Current()
	if err != nil {
		return err
	}
	if err := layout.VerifyRelease(current); err != nil {
		return err
	}
	_, hostConfigErr := os.Stat("/etc/terrascale-orchestrator/host.json")
	start := systemd == "/etc/systemd/system" &&
		(unit == selfupdate.HostUnit || unit == selfupdate.ControllerUnit) && hostConfigErr == nil
	return c.installNetBirdAgent(layout.BinaryPath(current), systemd, start)
}

func verifyIdentityRekeyBinaries(ctx context.Context, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, layout selfupdate.Layout) error {
	if err := accepted.Validate(); err != nil {
		return err
	}
	identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Environment: accepted.Environment, Cell: strings.ToLower(accepted.Cell)}
	if inputs.ChainIdentity != identity {
		return errors.New("identity rekey binary roots belong to another accepted identity")
	}
	roots, err := trust.VerifyRootChain(inputs.Genesis, identity, inputs.Chain)
	if err != nil {
		return err
	}
	inputs.Roots = roots
	c := command{ctx: ctx}
	for _, read := range []func() (string, error){layout.Current, layout.KnownGood} {
		digest, err := read()
		if err != nil {
			return err
		}
		if digest == "" {
			return errors.New("identity rekey requires compatible current and known-good releases")
		}
		if err := c.checkControllerRelease(layout, digest, accepted, inputs); err != nil {
			return err
		}
	}
	return c.checkControllerTransitions(layout, accepted, inputs, false, "")
}

func (c command) checkControllerRelease(layout selfupdate.Layout, digest string, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) error {
	bad, err := layout.KnownBad()
	if err != nil {
		return err
	}
	if bad[digest] {
		return selfupdate.ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return err
	}
	if digest == accepted.Binary.SHA256 {
		info, err := os.Stat(layout.BinaryPath(digest))
		if err != nil || info.Size() != accepted.Binary.Size {
			return selfupdate.ErrInvalid
		}
	} else {
		receipt, delegation, err := layout.ReleaseReceipt(digest)
		if err != nil {
			return err
		}
		envelope, err := trust.DecodeEnvelope(receipt)
		if err != nil {
			return err
		}
		var verified release.HistoricalBinary
		switch envelope.Scope.Domain {
		case release.BinaryDomain:
			verified, err = release.VerifyBinaryHistorical(receipt, delegation, inputs.Roots.Historical, release.BinaryExpectation{Environment: accepted.Environment})
		case release.UpdateReceiptDomain:
			verified, err = release.VerifyBinaryUpdateHistorical(receipt, delegation, inputs.Roots.Historical,
				release.UpdateExpectation{Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture})
		default:
			return errors.New("controller release has an unsupported receipt domain")
		}
		if err != nil {
			return err
		}
		if !verified.IsVerified() || verified.Receipt().SHA256 != digest || verified.Receipt().GOARCH != accepted.Binary.Architecture {
			return selfupdate.ErrInvalid
		}
	}
	return checkAcceptedBinary(c.ctx, layout.BinaryPath(digest), accepted)
}

func (c command) checkControllerTransitions(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked string) error {
	return c.checkControllerSelections(layout, accepted, inputs, starting, baked, "")
}

func (c command) checkControllerSelections(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked, unverified string) error {
	activation, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) && unverified != "" {
		activation, err = layout.RecoveryActivation()
		pending = err == nil && activation.Unit == selfupdate.ControllerUnit && activation.Target == unverified
		if err == nil && !pending {
			return selfupdate.ErrInvalid
		}
	}
	if err != nil {
		return err
	}
	if pending {
		if err := c.checkControllerRelease(layout, activation.Previous, accepted, inputs); err != nil {
			return fmt.Errorf("controller rollback predecessor: %w", err)
		}
		if activation.Target != unverified {
			if err := c.checkControllerRelease(layout, activation.Target, accepted, inputs); err != nil {
				return err
			}
		}
	}
	{
		current, err := layout.Current()
		if err != nil {
			return err
		}
		if current != "" && current != unverified {
			if err := c.checkControllerRelease(layout, current, accepted, inputs); err != nil {
				return err
			}
		} else if current == "" {
			if !starting || baked == "" {
				return errors.New("accepted controller has no current release")
			}
			if err := checkAcceptedBinary(c.ctx, baked, accepted); err != nil {
				return err
			}
		}
	}
	delegate, err := layout.Delegate()
	if err != nil {
		return err
	}
	if delegate != "" {
		if err := c.checkControllerRelease(layout, delegate, accepted, inputs); err != nil {
			return err
		}
	}
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := c.checkControllerRelease(layout, intent.Target, accepted, inputs); err != nil {
			return fmt.Errorf("controller restore target: %w", err)
		}
	}
	return nil
}

func (c command) prepare(args []string) error {
	flags := flag.NewFlagSet("prepare", flag.ContinueOnError)
	layout := addLayout(flags)
	proof := addProof(flags)
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	baked := flags.String("baked-binary", selfupdate.DefaultBakedBinary, "image-installed binary")
	systemd := flags.String("systemd-dir", "/etc/systemd/system", "unit directory that takes the node's self-update drop-ins")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, err := controllerTrust(*unit)
	if err != nil {
		return err
	}
	rollbackOnly := false
	if accepted != nil {
		rollbackOnly, err = c.checkControllerRecovery(layout.layout(), *accepted, inputs, true, *baked)
		if err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			if rollbackOnly {
				return err
			}
			current, currentErr := layout.layout().Current()
			good, goodErr := layout.layout().KnownGood()
			if currentErr != nil || goodErr != nil || current == "" || good == "" {
				return errors.Join(err, currentErr, goodErr)
			}
			if err := c.checkControllerRelease(layout.layout(), current, *accepted, inputs); err != nil {
				return err
			}
			if err := c.checkControllerRelease(layout.layout(), good, *accepted, inputs); err != nil {
				return err
			}
			_, printErr := fmt.Fprintf(c.output, "selfupdate prepare unit=%s held: compatible current and known-good; no effects\n", *unit)
			return printErr
		}
	}
	// The runtime secret mounts below belong to the host (TS-745).
	if layout.layout().Root == selfupdate.DefaultRoot {
		if moved, err := selfupdate.RunInHostMounts(c.ctx, c.output, os.Stderr); moved || err != nil {
			return err
		}
	}
	if !rollbackOnly && c.delegate(layout.layout(), append([]string{"prepare"}, args...)) {
		if err := c.backstopPrepare(layout.layout(), *unit); err != nil {
			return err
		}
		unlock, err := layout.layout().Lock()
		if err != nil {
			return err
		}
		defer unlock()
		if err := c.installCurrentNetBirdAgent(layout.layout(), *systemd, *unit); err != nil {
			slog.Warn("self-update could not prepare the NetBird worker", "error", err)
		}
		return nil
	}
	check, err := proof.check(*layout.root, *unit)
	if err != nil {
		return err
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	defer unlock()
	accepted, inputs, err = controllerTrust(*unit)
	if err != nil {
		return err
	}
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout.layout(), *accepted, inputs, true, *baked); err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
		if _, err := c.recoverControllerActivation(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	outcome, err := selfupdate.Prepare(layout.layout(), *unit, *baked, check, c.now())
	if err != nil {
		return err
	}
	current, err := layout.layout().Current()
	if err != nil {
		return err
	}
	if _, err = fmt.Fprintf(c.output, "selfupdate prepare unit=%s outcome=%s current=%s\n", *unit, outcome, current); err != nil {
		return err
	}
	// The controller process cannot write its credential directory or
	// controller.json; its armed material generation installs here (TS-668).
	if *unit == selfupdate.ControllerUnit {
		material, err := installGeneration(c.now())
		if err != nil {
			return err
		}
		if material != "" {
			if _, err := fmt.Fprintf(c.output, "selfupdate prepare material-generation: %s\n", material); err != nil {
				return err
			}
		}
	}
	// A node whose image predates a drop-in gets it from the release that
	// runs this step; a failure must not stop the unit's start.
	changed := false
	for _, dropin := range []struct {
		name    string
		install func(string) (bool, error)
	}{{"host-setup", selfupdate.InstallHostSetupDropin}, {"bootstrap", selfupdate.InstallBootstrapDropin},
		{"controller-install", selfupdate.InstallControllerInstallDropin}, {"watchdog", selfupdate.InstallWatchdogLoggingDropin}} {
		if installed, err := dropin.install(*systemd); err != nil {
			slog.Warn("self-update could not install the "+dropin.name+" drop-in", "error", err)
		} else if installed {
			changed = true
			if _, err := fmt.Fprintf(c.output, "selfupdate prepare installed the %s drop-in\n", dropin.name); err != nil {
				return err
			}
		}
	}
	if err := c.installCurrentNetBirdAgent(layout.layout(), *systemd, *unit); err != nil {
		slog.Warn("self-update could not prepare the NetBird worker", "error", err)
	}
	// The drop-ins belong to other units, which read them at their next
	// start once systemd reloads.
	if changed {
		if err := daemonReload(c.ctx); err != nil {
			slog.Warn("self-update could not reload systemd; the drop-ins apply from the next boot", "error", err)
		}
	}
	// The unit's runtime secrets live in memory (TS-745); this root step
	// mounts their directories before the unit's process starts. A failure
	// must not fail prepare (the baked fallback would run instead): the host
	// agent refuses to write those secrets to disk.
	if layout.layout().Root == selfupdate.DefaultRoot {
		if err := memoryRuntime(*unit); err != nil {
			slog.Warn("self-update could not mount the runtime secrets in memory", "unit", *unit, "error", err)
		}
	}
	return nil
}

func (c command) watchdog(args []string) error {
	flags := flag.NewFlagSet("watchdog", flag.ContinueOnError)
	layout := addLayout(flags)
	proof := addProof(flags)
	unit := flags.String("unit", "", "systemd unit that executes the current release")
	if err := parse(flags, args); err != nil {
		return err
	}
	accepted, inputs, err := controllerTrust(*unit)
	if err != nil {
		return err
	}
	rollbackOnly := false
	if accepted != nil {
		rollbackOnly, err = c.checkControllerRecovery(layout.layout(), *accepted, inputs, false, "")
		if err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			return err
		}
	}
	delegated := !rollbackOnly && c.delegate(layout.layout(), append([]string{"watchdog"}, args...))
	var check selfupdate.ProofCheck
	if !delegated {
		var err error
		if check, err = proof.check(*layout.root, *unit); err != nil {
			return err
		}
	}
	unlock, err := layout.layout().Lock()
	if err != nil {
		return err
	}
	accepted, inputs, err = controllerTrust(*unit)
	if err != nil {
		unlock()
		return err
	}
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout.layout(), *accepted, inputs, false, ""); err != nil {
			unlock()
			return err
		}
		if err := c.requireControllerCompletion(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
		if _, err := c.recoverControllerActivation(layout.layout(), *accepted, inputs); err != nil {
			unlock()
			return err
		}
	}
	var outcome selfupdate.Outcome
	var activation selfupdate.Activation
	if delegated {
		outcome, activation, err = selfupdate.Backstop(layout.layout(), c.now())
	} else {
		outcome, activation, err = selfupdate.Watch(layout.layout(), *unit, check, c.now())
	}
	if err != nil {
		unlock()
		return err
	}
	// The rollout step runs after the check, so a slow or stuck step never
	// delays a rollback, and before the restart below serves what it owes.
	if !delegated && (*unit == selfupdate.ControllerUnit || *unit == selfupdate.HostUnit) && *proof.config != "" {
		unlock()
		c.rolloutStep(layout.layout(), *unit, *proof.config)
		if unlock, err = layout.layout().Lock(); err != nil {
			return err
		}
	}
	// A rollback leaves a restart obligation until the unit restarts, so a
	// failed systemctl call, an output error or a crash after the link moved
	// is retried by the next timer run instead of reading as idle.
	owed, err := layout.layout().RestartPending(*unit)
	unlock()
	if err != nil {
		return err
	}
	// An idle run runs every 15 s and says nothing. A pending run also repeats
	// every 15 s while an activation waits, so it is debug; rollbacks are warnings.
	if outcome != selfupdate.OutcomeIdle {
		level := slog.LevelInfo
		switch outcome {
		case selfupdate.OutcomePending:
			level = slog.LevelDebug
		case selfupdate.OutcomeRolledBack:
			level = slog.LevelWarn
		}
		slog.Log(c.ctx, level, "selfupdate watchdog", observability.ComponentKey, "selfupdate",
			"unit", *unit, "outcome", string(outcome), "activation", activation.ActivationID, "target", activation.Target)
	}
	if owed {
		if err := c.restart(c.ctx, *unit); err != nil {
			return err
		}
		unlock, err := layout.layout().Lock()
		if err != nil {
			return err
		}
		defer unlock()
		return layout.layout().ClearRestartPending(*unit)
	}
	return nil
}

func (c command) backstopPrepare(layout selfupdate.Layout, unit string) error {
	unlock, err := layout.Lock()
	if err != nil {
		return err
	}
	defer unlock()
	accepted, inputs, err := controllerTrust(unit)
	if err != nil {
		return err
	}
	recovered := false
	if accepted != nil {
		if _, err := c.checkControllerRecovery(layout, *accepted, inputs, true, ""); err != nil {
			return err
		}
		if err := c.requireControllerCompletion(layout, *accepted, inputs); err != nil {
			return err
		}
		recovered, err = c.recoverControllerActivation(layout, *accepted, inputs)
		if err != nil {
			return err
		}
	}
	outcome, activation, err := selfupdate.Backstop(layout, c.now())
	if err != nil {
		return err
	}
	// This start serves the restart the rollback owes the unit.
	if recovered || outcome == selfupdate.OutcomeRolledBack && activation.Unit == unit {
		if err := layout.ClearRestartPending(unit); err != nil {
			return err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return err
	}
	if err := layout.VerifyRelease(current); err != nil {
		return fmt.Errorf("current release does not verify: %w", err)
	}
	return nil
}

func (c command) requireControllerCompletion(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) error {
	present, err := acceptedJournalPresent()
	if err != nil || !present {
		return err
	}
	current, err := layout.Current()
	if err != nil || current == "" {
		return errors.New("identity rekey completion requires a trusted current binary")
	}
	rollback, err := c.controllerRollback(layout, accepted, inputs)
	if err != nil {
		return err
	}
	if current == rollback.Target {
		current = rollback.Previous
	}
	if err := c.checkControllerRelease(layout, current, accepted, inputs); err != nil {
		return err
	}
	return completionProbe(c.ctx, layout.BinaryPath(current))
}

func (c command) checkControllerRelease(layout selfupdate.Layout, digest string, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) error {
	bad, err := layout.KnownBad()
	if err != nil {
		return err
	}
	if bad[digest] {
		return selfupdate.ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return err
	}
	if digest == accepted.Binary.SHA256 {
		info, err := os.Stat(layout.BinaryPath(digest))
		if err != nil || info.Size() != accepted.Binary.Size {
			return selfupdate.ErrInvalid
		}
	} else {
		receipt, delegation, err := layout.ReleaseReceipt(digest)
		if err != nil {
			return err
		}
		envelope, err := trust.DecodeEnvelope(receipt)
		if err != nil {
			return err
		}
		var verified release.HistoricalBinary
		switch envelope.Scope.Domain {
		case release.BinaryDomain:
			verified, err = release.VerifyBinaryHistorical(receipt, delegation, inputs.Roots.Historical, release.BinaryExpectation{Environment: accepted.Environment})
		case release.UpdateReceiptDomain:
			verified, err = release.VerifyBinaryUpdateHistorical(receipt, delegation, inputs.Roots.Historical,
				release.UpdateExpectation{Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture})
		default:
			return errors.New("controller release has an unsupported receipt domain")
		}
		if err != nil {
			return err
		}
		if !verified.IsVerified() || verified.Receipt().SHA256 != digest || verified.Receipt().GOARCH != accepted.Binary.Architecture {
			return selfupdate.ErrInvalid
		}
	}
	return checkAcceptedBinary(c.ctx, layout.BinaryPath(digest), accepted)
}

func (c command) checkControllerRecovery(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked string) (bool, error) {
	rollback, err := c.controllerRollback(layout, accepted, inputs)
	if err != nil {
		return false, err
	}
	return rollback.Target != "", c.checkControllerSelections(layout, accepted, inputs, starting, baked, rollback.Target)
}

func (c command) controllerRollback(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) (selfupdate.Activation, error) {
	activation, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) {
		activation, err = layout.RecoveryActivation()
		if err != nil {
			return selfupdate.Activation{}, err
		}
		if activation.Unit == selfupdate.ControllerUnit {
			return activation, nil
		}
		return selfupdate.Activation{}, nil
	}
	if err != nil {
		return selfupdate.Activation{}, err
	}
	if pending && activation.Unit == selfupdate.ControllerUnit && c.checkControllerRelease(layout, activation.Target, accepted, inputs) != nil {
		return activation, c.ctx.Err()
	}
	intents, err := layout.PendingRestores()
	if err != nil {
		return selfupdate.Activation{}, err
	}
	for _, intent := range intents {
		if intent.Unit == selfupdate.ControllerUnit {
			return selfupdate.Activation{Target: intent.Rejected, Previous: intent.Target, Unit: intent.Unit}, nil
		}
	}
	return selfupdate.Activation{}, nil
}

func (c command) recoverControllerActivation(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs) (bool, error) {
	activation, err := c.controllerRollback(layout, accepted, inputs)
	if err != nil || activation.Target == "" {
		return false, err
	}
	if err := c.checkControllerSelections(layout, accepted, inputs, false, "", activation.Target); err != nil {
		return false, err
	}
	_, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) {
		outcome, _, err := selfupdate.Watch(layout, activation.Unit, selfupdate.ProofCheck{}, c.now())
		return outcome == selfupdate.OutcomeRolledBack, err
	} else if err != nil {
		return false, err
	}
	if !pending {
		_, _, err := selfupdate.Watch(layout, activation.Unit, selfupdate.ProofCheck{}, c.now())
		return err == nil, err
	}
	return selfupdate.Restore(layout, activation.Previous, activation.Target, activation.Unit)
}

func (c command) checkControllerSelections(layout selfupdate.Layout, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, starting bool, baked, unverified string) error {
	activation, pending, err := layout.Pending()
	if errors.Is(err, selfupdate.ErrUnreadableActivation) && unverified != "" {
		activation, err = layout.RecoveryActivation()
		pending = err == nil && activation.Unit == selfupdate.ControllerUnit && activation.Target == unverified
		if err == nil && !pending {
			return selfupdate.ErrInvalid
		}
	}
	if err != nil {
		return err
	}
	if pending {
		if err := c.checkControllerRelease(layout, activation.Previous, accepted, inputs); err != nil {
			return fmt.Errorf("controller rollback predecessor: %w", err)
		}
		if activation.Target != unverified {
			if err := c.checkControllerRelease(layout, activation.Target, accepted, inputs); err != nil {
				return err
			}
		}
	}
	{
		current, err := layout.Current()
		if err != nil {
			return err
		}
		if current != "" && current != unverified {
			if err := c.checkControllerRelease(layout, current, accepted, inputs); err != nil {
				return err
			}
		} else if current == "" {
			if !starting || baked == "" {
				return errors.New("accepted controller has no current release")
			}
			if err := checkAcceptedBinary(c.ctx, baked, accepted); err != nil {
				return err
			}
		}
	}
	delegate, err := layout.Delegate()
	if err != nil {
		return err
	}
	if delegate != "" {
		if err := c.checkControllerRelease(layout, delegate, accepted, inputs); err != nil {
			return err
		}
	}
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := c.checkControllerRelease(layout, intent.Target, accepted, inputs); err != nil {
			return fmt.Errorf("controller restore target: %w", err)
		}
	}
	return nil
}

func Watch(layout Layout, unit string, proof ProofCheck, now time.Time) (Outcome, Activation, error) {
	// A rollout restore interrupted before its link moved is finished
	// first, so neither the watchdog's restart nor the unit's start ever
	// runs the release the restore rejected.
	if err := layout.finishRestores(); err != nil {
		return OutcomeIdle, Activation{}, fmt.Errorf("finish interrupted restore: %w", err)
	}
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return layout.resolveUnreadable(err)
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	if activation.Unit != unit {
		// Another unit's watchdog resolves this activation. Once it is long
		// past its deadline no functioning watchdog is left to do so (a
		// mistyped unit, or a unit without the drop-ins): roll it back so it
		// cannot block every later activation on this node.
		if now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
			return OutcomePending, activation, nil
		}
		slog.Warn("self-update activation of an unwatched unit expired; rolling back",
			"activation", activation.ActivationID, "unit", activation.Unit)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// rollback marks the target known bad before it moves the link and
	// removes the record. A known-bad target therefore means a rollback was
	// committed and interrupted: finish it instead of accepting a proof.
	knownBad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if knownBad[activation.Target] {
		slog.Warn("self-update rollback was interrupted; finishing it", "activation", activation.ActivationID)
		if err := layout.rollback(activation); err != nil {
			return OutcomeRolledBack, activation, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return OutcomeRolledBack, activation, nil
	}
	// Only a target that is actually selected can be confirmed. Otherwise
	// the activation stays pending until its deadline rolls it back.
	current, err := layout.Current()
	if err != nil {
		return OutcomePending, activation, err
	}
	targetErr := layout.VerifyRelease(activation.Target)
	if targetErr == nil && current == activation.Target && len(proof.PublicKey) == ed25519.PublicKeySize {
		if wire, err := readProof(proof.File); err == nil {
			if verified, err := VerifyVersionProof(wire, proof.PublicKey, activation, now); err == nil && !processRunning(verified.ProcessID) {
				// A proof only confirms while the process that signed it
				// still runs: one that crashed right after proving must not
				// confirm the activation at the next check.
				slog.Warn("self-update version proof process is gone", "activation", activation.ActivationID, "pid", verified.ProcessID)
			} else if err == nil {
				if err := layout.rememberConfirmed(activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				// The confirmed release runs the image's root steps from
				// now on (Delegate).
				if err := layout.flipLink(knownGoodLink, activation.Target); err != nil {
					return OutcomePending, activation, err
				}
				if err := os.Remove(layout.activationPath()); err != nil {
					return OutcomePending, activation, err
				}
				if err := syncDir(layout.Root); err != nil {
					return OutcomeConfirmed, activation, err
				}
				recordResolution(activation, OutcomeConfirmed)
				return OutcomeConfirmed, activation, nil
			} else {
				slog.Warn("self-update version proof rejected", "activation", activation.ActivationID, "error", err)
			}
		} else if !errors.Is(err, os.ErrNotExist) {
			slog.Warn("self-update version proof unreadable", "activation", activation.ActivationID, "error", err)
		}
	}
	if targetErr == nil && now.Before(activation.Deadline) {
		return OutcomePending, activation, nil
	}
	if err := layout.rollback(activation); err != nil {
		return OutcomeRolledBack, activation, err
	}
	recordResolution(activation, OutcomeRolledBack)
	return OutcomeRolledBack, activation, nil
}

func Backstop(layout Layout, now time.Time) (Outcome, Activation, error) {
	activation, pending, err := layout.Pending()
	if errors.Is(err, ErrUnreadableActivation) {
		return OutcomeIdle, Activation{}, nil
	}
	if err != nil || !pending {
		return OutcomeIdle, Activation{}, err
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return OutcomePending, activation, err
	}
	if !bad[activation.Target] && layout.VerifyRelease(activation.Target) == nil && now.Before(activation.Deadline.Add(OrphanedActivationGrace)) {
		return OutcomePending, activation, nil
	}
	slog.Warn("self-update activation is damaged or outlived its deadline; rolling back",
		"activation", activation.ActivationID, "unit", activation.Unit)
	if err := layout.rollback(activation); err != nil {
		return OutcomeRolledBack, activation, err
	}
	recordResolution(activation, OutcomeRolledBack)
	return OutcomeRolledBack, activation, nil
}

func (layout Layout) resolveUnreadable(cause error) (Outcome, Activation, error) {
	_, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return OutcomeIdle, Activation{}, err
	}
	outcome := OutcomeIdle
	activation, recoveryErr := layout.RecoveryActivation()
	if recoveryErr == nil && layout.VerifyRelease(activation.Previous) == nil {
		current, err := layout.Current()
		if err != nil {
			return OutcomePending, activation, err
		}
		if current != activation.Target && current != activation.Previous {
			return OutcomePending, activation, fmt.Errorf("%w: unreadable activation does not own current selection", ErrInvalid)
		}
		if err := layout.markKnownBad(activation.Target); err != nil {
			return OutcomePending, activation, err
		}
		if current == activation.Target {
			if err := layout.flipCurrent(activation.Previous); err != nil {
				return OutcomePending, activation, err
			}
		}
		if err := layout.markRestartPending(activation.Unit); err != nil {
			return OutcomePending, activation, err
		}
		outcome = OutcomeRolledBack
	}
	quarantine := layout.activationPath() + ".unreadable-" + time.Now().UTC().Format("20060102T150405.000000000Z")
	if err := os.Rename(layout.activationPath(), quarantine); err != nil {
		return OutcomePending, activation, err
	}
	slog.Warn("self-update activation record was unreadable and was moved aside",
		"path", quarantine, "outcome", outcome, "error", cause)
	return outcome, activation, syncDir(layout.Root)
}

func (layout Layout) rollback(activation Activation) error {
	if err := layout.markKnownBad(activation.Target); err != nil {
		return err
	}
	if err := layout.VerifyRelease(activation.Previous); err != nil {
		return fmt.Errorf("previous release cannot be restored: %w", err)
	}
	if err := layout.flipCurrent(activation.Previous); err != nil {
		return err
	}
	// The rejected process may still run: keep a restart obligation that
	// outlives this invocation before the activation record goes away.
	if err := layout.markRestartPending(activation.Unit); err != nil {
		return err
	}
	if err := os.Remove(layout.activationPath()); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

func Prepare(layout Layout, unit, bakedBinary string, proof ProofCheck, now time.Time) (Outcome, error) {
	if _, err := Seed(layout, bakedBinary); err != nil {
		return OutcomeIdle, fmt.Errorf("seed baked release: %w", err)
	}
	// Prepare runs while the unit (re)starts, so the process behind any
	// existing proof is gone: a proof never confirms across a restart. The
	// new process proves itself again for the watchdog; prepare only
	// resolves expired, unwatched or unreadable activations; its proof
	// argument is accepted for the drop-in's flags and not used to confirm.
	outcome, activation, err := Watch(layout, unit, ProofCheck{}, now)
	if err != nil {
		return outcome, err
	}
	// The unit is starting now, so any restart a rollback still owed it is
	// being served by this start.
	if unitRE.MatchString(unit) {
		if err := layout.ClearRestartPending(unit); err != nil {
			return outcome, err
		}
	}
	current, err := layout.Current()
	if err != nil {
		return outcome, err
	}
	// The units on a node share the current link. A unit never starts the
	// unconfirmed target of another unit's activation: it cannot prove it,
	// and that activation's rollback does not restart it. Its restart policy
	// retries once the activation is resolved.
	if outcome == OutcomePending && activation.Unit != unit && current == activation.Target {
		return outcome, fmt.Errorf("%w: %s waits for the pending activation of %s", ErrInvalid, unit, activation.Unit)
	}
	if err := layout.VerifyRelease(current); err != nil {
		return outcome, fmt.Errorf("current release does not verify: %w", err)
	}
	if removed, err := layout.PruneReleases(now); err != nil {
		slog.Warn("self-update release pruning failed", "error", err)
	} else if len(removed) > 0 {
		slog.Info("self-update pruned settled releases", "releases", removed)
	}
	return outcome, nil
}

func (layout Layout) PruneReleases(now time.Time) ([]string, error) {
	current, err := layout.Current()
	if err != nil {
		return nil, err
	}
	if current == "" {
		return nil, nil
	}
	keep := map[string]bool{current: true}
	if known, err := layout.KnownGood(); err != nil {
		return nil, err
	} else if known != "" {
		keep[known] = true
	}
	confirmed, err := layout.ConfirmedReleases()
	if err != nil {
		return nil, err
	}
	for _, digest := range confirmed {
		keep[digest] = true
	}
	activation, pending, err := layout.Pending()
	if err != nil {
		return nil, err
	}
	if pending {
		keep[activation.Target], keep[activation.Previous] = true, true
	}
	knownBad, err := layout.KnownBad()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.releasesPath())
	if err != nil {
		return nil, err
	}
	var removed []string
	for _, entry := range entries {
		digest := entry.Name()
		if !digestRE.MatchString(digest) || keep[digest] {
			continue
		}
		directory := layout.ReleaseDir(digest)
		info, err := os.Lstat(directory)
		if err != nil || !info.IsDir() {
			continue
		}
		if _, err := os.Lstat(filepath.Join(directory, bakedMarkerFile)); err == nil {
			continue
		}
		if !knownBad[digest] && now.Sub(info.ModTime()) < StagedReleaseRetention {
			continue
		}
		if err := layout.checkOwned(directory, true); err != nil {
			return removed, err
		}
		if err := os.RemoveAll(directory); err != nil {
			return removed, err
		}
		removed = append(removed, digest)
	}
	if len(removed) > 0 {
		return removed, syncDir(layout.releasesPath())
	}
	return removed, nil
}

func Restore(layout Layout, digest, rejected, unit string) (bool, error) {
	if !digestRE.MatchString(digest) || !digestRE.MatchString(rejected) || digest == rejected || !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: restore target", ErrInvalid)
	}
	if err := layout.finishRestores(); err != nil {
		return false, err
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return false, err
	} else if knownBad[digest] {
		return false, ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return false, err
	}
	activation, pending, err := layout.Pending()
	if err != nil {
		return false, err
	}
	if pending {
		if activation.Unit != unit || activation.Target != rejected || activation.Previous != digest {
			return false, fmt.Errorf("%w: activation %s is pending for another release", ErrInvalid, activation.ActivationID)
		}
		if err := layout.rollback(activation); err != nil {
			return true, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return true, nil
	}
	current, err := layout.Current()
	if err != nil {
		return false, err
	}
	switch current {
	case digest:
		// The unit never left digest, but the rollout rejected the other
		// release: this node must refuse it from now on too. Nothing
		// changed the selection, so no restart is owed.
		return false, layout.markKnownBad(rejected)
	case rejected:
	default:
		return false, fmt.Errorf("%w: the current release is neither the restore target nor the rejected release", ErrInvalid)
	}
	// There is no activation record to recover an interrupted restore
	// from, so a durable intent names the target first; finishRestore
	// completes the switch from it at any later point.
	intent, err := protocol.EncodeJSON(RestoreIntent{Schema: restoreIntentSchema, Unit: unit, Target: digest, Rejected: rejected})
	if err != nil {
		return false, err
	}
	if err := writeFileAtomic(layout.restoreIntentPath(unit), intent, 0o644); err != nil {
		return false, err
	}
	if err := layout.finishRestore(unit); err != nil {
		return true, err
	}
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Actor:   decisionlog.Actor{Slice: "selfupdate"},
		Kind:    decisionlog.KindRollback,
		Subject: memberSubject(unit),
		Summary: "Restored release " + shortDigest(digest) + " on " + unit,
		Reason:  "A rollout rolled back the release this unit ran; that release is now known bad on this node.",
		Rule:    "selfupdate.restore",
		Status:  decisionlog.StatusRolledBack,
		Attrs:   map[string]string{"version": digest, "rejected": rejected},
	})
	return true, nil
}

func (layout Layout) finishRestores() error {
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := layout.finishRestore(intent.Unit); err != nil {
			return err
		}
	}
	return nil
}

func (layout Layout) PendingRestores() ([]RestoreIntent, error) {
	if err := layout.validate(); err != nil {
		return nil, err
	}
	if err := layout.checkOwned(layout.Root, true); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.Root)
	if err != nil {
		return nil, err
	}
	var intents []RestoreIntent
	for _, entry := range entries {
		unit, ok := strings.CutPrefix(entry.Name(), restoreIntentPrefix)
		if !ok {
			continue
		}
		unit, ok = strings.CutSuffix(unit, ".json")
		if !ok || !unitRE.MatchString(unit) {
			return nil, fmt.Errorf("%w: restore intent %q", ErrUnsafe, entry.Name())
		}
		if _, pending, err := layout.Pending(); err != nil {
			return nil, err
		} else if pending {
			return nil, fmt.Errorf("%w: restore intent of %s next to a pending activation", ErrUnsafe, unit)
		}
		intent, err := layout.readRestoreIntent(unit)
		if err != nil {
			return nil, err
		}
		intents = append(intents, intent)
	}
	return intents, nil
}

func (layout Layout) readRestoreIntent(unit string) (RestoreIntent, error) {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); err != nil {
		return RestoreIntent{}, err
	}
	data, err := readBounded(path, maxStateBytes)
	if err != nil {
		return RestoreIntent{}, err
	}
	var intent RestoreIntent
	if err := protocol.DecodeStrict(data, &intent, maxStateBytes); err != nil {
		return RestoreIntent{}, err
	}
	if intent.Schema != restoreIntentSchema || intent.Unit != unit || !digestRE.MatchString(intent.Target) ||
		!digestRE.MatchString(intent.Rejected) || intent.Target == intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: restore intent", ErrInvalid)
	}
	current, err := layout.Current()
	if err != nil {
		return RestoreIntent{}, err
	}
	if current != intent.Target && current != intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: current differs from recorded restore", ErrUnsafe)
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return RestoreIntent{}, err
	}
	if bad[intent.Target] {
		return RestoreIntent{}, ErrKnownBad
	}
	if err := layout.VerifyRelease(intent.Target); err != nil {
		return RestoreIntent{}, fmt.Errorf("restore target cannot be restored: %w", err)
	}
	return intent, nil
}

func (layout Layout) finishRestore(unit string) error {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	intent, err := layout.readRestoreIntent(unit)
	if err != nil {
		return err
	}
	if err := layout.markKnownBad(intent.Rejected); err != nil {
		return err
	}
	if err := layout.markRestartPending(unit); err != nil {
		return err
	}
	if current, err := layout.Current(); err != nil {
		return err
	} else if current != intent.Target {
		if err := layout.flipCurrent(intent.Target); err != nil {
			return err
		}
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

func (layout Layout) markRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	return writeFileAtomic(layout.restartMarkerPath(unit), []byte(unit+"\n"), 0o644)
}

func (layout Layout) RestartPending(unit string) (bool, error) {
	if !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: unit", ErrInvalid)
	}
	err := layout.checkOwned(layout.restartMarkerPath(unit), false)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return err == nil, err
}

func (layout Layout) ClearRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	if err := os.Remove(layout.restartMarkerPath(unit)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func checkAcceptedIdentity(input io.Reader, args []string) error {
	if len(args) != 0 {
		return errors.New("check-accepted-identity takes canonical accepted identity on stdin")
	}
	wire, err := io.ReadAll(io.LimitReader(input, bootstrapstart.MaxAcceptedIdentityBytes+1))
	if err != nil {
		return err
	}
	_, err = bootstrapstart.DecodeAcceptedIdentity(wire)
	return err
}

func checkAcceptedBinaryContract(ctx context.Context, binary string, accepted bootstrapstart.AcceptedIdentity) error {
	wire, err := bootstrapstart.EncodeAcceptedIdentity(accepted)
	if err != nil {
		return err
	}
	probe := func(wire []byte) error {
		probeCtx, cancel := context.WithTimeout(ctx, 5*time.Second)
		defer cancel()
		command := exec.CommandContext(probeCtx, binary, "selfupdate", "check-accepted-identity")
		command.Stdin = bytes.NewReader(wire)
		command.Stdout, command.Stderr = io.Discard, io.Discard
		command.WaitDelay = time.Second
		return command.Run()
	}
	if err := probe(wire); err != nil {
		return fmt.Errorf("release cannot read the accepted identity contract: %w", err)
	}
	if err := probe([]byte(`{}`)); err == nil {
		return errors.New("release accepted an invalid identity contract")
	}
	return nil
}

func runCompletionProbeAs(ctx context.Context, binary string, uid, gid uint32) error {
	if uid == 0 || gid == 0 || !filepath.IsAbs(binary) {
		return errors.New("completion probe requires service ownership and an absolute binary")
	}
	probeCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()
	command := exec.CommandContext(probeCtx, binary, "identity-rekey-completion-check", "--config", "/etc/terrascale-orchestrator/controller.json")
	command.SysProcAttr = &syscall.SysProcAttr{Credential: &syscall.Credential{Uid: uid, Gid: gid}}
	command.Stdout, command.Stderr = io.Discard, io.Discard
	command.WaitDelay = time.Second
	if err := command.Run(); err != nil {
		return fmt.Errorf("read-only identity rekey completion probe refused: %w", err)
	}
	return nil
}

func verifyIdentityRekeyCandidate(ctx context.Context, accepted bootstrapstart.AcceptedIdentity, inputs bootstrapstart.TrustInputs, candidate string, receipt, delegation []byte, now time.Time, owner uint32, unsafeAncestors bool) error {
	if err := accepted.Validate(); err != nil {
		return err
	}
	identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Environment: accepted.Environment, Cell: strings.ToLower(accepted.Cell)}
	if inputs.ChainIdentity != identity {
		return trust.ErrScopeMismatch
	}
	roots, err := trust.VerifyRootChain(inputs.Genesis, identity, inputs.Chain)
	if err != nil {
		return err
	}
	return verifyIdentityRekeyCandidateRoots(ctx, accepted, candidate, receipt, delegation, now, owner, unsafeAncestors, roots.Current)
}

func verifyIdentityRekeyCandidateRoots(ctx context.Context, accepted bootstrapstart.AcceptedIdentity, candidate string, receipt, delegation []byte, now time.Time, owner uint32, unsafeAncestors bool, roots trust.Keyring) error {
	policy := selfupdate.ReceiptPolicy{Roots: roots, Environment: accepted.Environment, Cell: accepted.Cell, Architecture: accepted.Binary.Architecture}
	verified, err := policy.Verify(receipt, delegation, now)
	if err != nil {
		return err
	}
	pin := verified.Receipt()
	if pin.SHA256 != accepted.Binary.SHA256 || pin.Bytes != accepted.Binary.Size || pin.GOARCH != accepted.Binary.Architecture {
		return selfupdate.ErrInvalid
	}
	if err := verifyCandidateOwnership(candidate, owner, unsafeAncestors); err != nil {
		return err
	}
	if err := bootstrapstart.VerifyIdentityRekeyBinaryFile(candidate, accepted.Binary); err != nil {
		return err
	}
	return checkAcceptedBinary(ctx, candidate, accepted)
}

func verifyCandidateOwnership(path string, owner uint32, unsafeAncestors bool) error {
	if !filepath.IsAbs(path) || filepath.Clean(path) != path {
		return selfupdate.ErrUnsafe
	}
	dir, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return err
	}
	for component := range strings.SplitSeq(strings.TrimPrefix(filepath.Dir(path), "/"), "/") {
		if component == "" {
			continue
		}
		next, err := unix.Openat(dir, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		unix.Close(dir)
		if err != nil {
			return err
		}
		dir = next
		var stat unix.Stat_t
		if !unsafeAncestors && (unix.Fstat(dir, &stat) != nil || stat.Uid != owner || stat.Mode&0o022 != 0) {
			unix.Close(dir)
			return selfupdate.ErrUnsafe
		}
	}
	defer unix.Close(dir)
	fd, err := unix.Openat(dir, filepath.Base(path), unix.O_RDONLY|unix.O_NOFOLLOW|unix.O_CLOEXEC|unix.O_NONBLOCK, 0)
	if err != nil {
		return err
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if unix.Fstat(fd, &stat) != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Uid != owner || stat.Nlink != 1 || stat.Mode&0o022 != 0 || stat.Mode&0o111 == 0 {
		return selfupdate.ErrUnsafe
	}
	return nil
}

func VerifyIdentityRekeyBinaryFile(path string, pin identityrekey.BinaryPin) error {
	_, err := verifyAcceptedBinaryFile(path, pin)
	return err
}

func verifyAcceptedBinaryFile(path string, pin identityrekey.BinaryPin) (RunningBinary, error) {
	return verifyBinaryFile(path, release.ImageReceipt{BinarySHA256: pin.SHA256, BinaryBytes: pin.Size, Architecture: pin.Architecture})
}

func verifyBinaryFile(path string, receipt release.ImageReceipt) (RunningBinary, error) {
	file, err := os.Open(path)
	if err != nil {
		return RunningBinary{}, fmt.Errorf("open running binary: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > release.MaxArtifactBytes ||
		info.Size() != receipt.BinaryBytes {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	parsed, err := elf.NewFile(file)
	if err != nil || parsed.Class != elf.ELFCLASS64 || parsed.Data != elf.ELFDATA2LSB {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	architecture := ""
	switch parsed.Machine {
	case elf.EM_X86_64:
		architecture = "amd64"
	case elf.EM_AARCH64:
		architecture = "arm64"
	default:
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	if architecture != receipt.Architecture {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	hash := sha256.New()
	read := io.NewSectionReader(file, 0, info.Size())
	count, err := io.Copy(hash, read)
	if err != nil || count != info.Size() {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	digest := hex.EncodeToString(hash.Sum(nil))
	if digest != receipt.BinarySHA256 {
		return RunningBinary{}, ErrRunningBinaryMismatch
	}
	return RunningBinary{SHA256: digest, Bytes: count, Architecture: architecture}, nil
}

func controllerStoppedState(output []byte) error {
	state := map[string]string{}
	for line := range strings.SplitSeq(strings.TrimSpace(string(output)), "\n") {
		key, value, ok := strings.Cut(line, "=")
		if !ok || state[key] != "" {
			return selfupdate.ErrInvalid
		}
		state[key] = value
	}
	if len(state) != 4 || state["ActiveState"] != "inactive" || state["SubState"] != "dead" || state["MainPID"] != "0" || state["ControlPID"] != "0" {
		return errors.New("identity rekey binary installation requires the controller stopped")
	}
	return nil
}

func readHostRuntime(path string) (hostRuntime, error) {
	file, err := os.Open(path)
	if err != nil {
		return hostRuntime{}, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, maxRoleConfigBytes+1))
	if err != nil || len(data) > maxRoleConfigBytes {
		return hostRuntime{}, errors.Join(err, errors.New("host config is unreadable or too large"))
	}
	var config struct {
		Host hostRuntime `json:"host"`
	}
	if err := json.Unmarshal(data, &config); err != nil {
		return hostRuntime{}, err
	}
	for _, root := range []string{config.Host.ManagedRuntimeRoot, config.Host.TerraBaseRoot} {
		if root != "" && (!filepath.IsAbs(root) || filepath.Clean(root) != root || root == "/") {
			return hostRuntime{}, fmt.Errorf("host runtime root %q is not clean and absolute", root)
		}
	}
	if config.Host.WorkloadGID == 0 && (config.Host.ManagedRuntimeRoot != "" || config.Host.TerraBaseRoot != "") {
		return hostRuntime{}, errors.New("host config has no workload group")
	}
	return config.Host, nil
}
